#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }
    // Parse shift amount and normalize to 0-25
    long val = strtol(argv[1], NULL, 10);
    int shift = (int)(val % 26);
    if (shift < 0) shift += 26;

    const char *input = argv[2];
    size_t len = strlen(input);
    if (len > 1024) { // matches the original limit (0x400)
        puts("USAGE");
        return 0;
    }

    for (size_t i = 0; i < len; ++i) {
        unsigned char c = (unsigned char)input[i];
        if (c >= 'A' && c <= 'Z') {
            putchar(((c - 'A' + shift) % 26) + 'A');
        } else if (c >= 'a' && c <= 'z') {
            putchar(((c - 'a' + shift) % 26) + 'a');
        } else {
            putchar(c);
        }
    }
    putchar('\n');
    return 0;
}
